"volvo-xc40-2019": {"features":{"safety":["8 airbags","Lane-keeping assist and blind spot warning","Automatic emergency braking","ESP stability and traction control","Hill-descent control"],"comfort":["9-inch portrait touchscreen with Android Auto and Apple CarPlay","Digital instrument cluster","LED headlights","Cruise control","Rear parking assist","18-inch alloy wheels"],"sources":[{"name":"Autocar India, Volvo XC40 Momentum, Inscription variants launched (16 Jul 2018)","url":"https://www.autocarindia.com/car-news/volvo-xc40-momentum-inscription-variants-launched-409052","as_of":"2026-10-15"},{"name":"Autocar India, full details of Volvo XC40 for India revealed (15 Dec 2017)","url":"https://www.autocarindia.com/car-news-amp/full-details-of-volvo-xc40-for-india-revealed-406825","as_of":"2026-10-15"}],"peek":"8 airbags · 9-inch touchscreen · Apple CarPlay","check":["Adaptive cruise control and Pilot Assist: Autocar India lists them for all versions, but also says the Momentum gets pla","Leather upholstery (our listing says leather; Autocar India names leather only on the R-Design)","Not on the Momentum: wireless charging, Harman Kardon sound, powered tailgate, heated seats"]},"variants":{"this":"Momentum","above":"R-Design and Inscription","ladder":["Momentum","R-Design","Inscription"],"lines":["The XC40 arrived in July 2018 as the D4 R-Design; the Momentum and Inscription were added two weeks later.","Prices then: Momentum Rs 39.9 lakh, R-Design Rs 42.9 lakh, Inscription Rs 43.9 lakh, ex-showroom.","The Momentum is the entry version: it misses wireless charging, the Harman Kardon system, the powered tailgate and heated seats.","Every version had the same D4 diesel, 8-speed automatic, all-wheel drive and the same safety kit."],"sources":[{"name":"Autocar India, Volvo XC40 Momentum, Inscription variants launched (16 Jul 2018)","url":"https://www.autocarindia.com/car-news/volvo-xc40-momentum-inscription-variants-launched-409052","as_of":"2026-10-15"},{"name":"Rushlane, new Volvo XC40 India launch (4 Jul 2018)","url":"https://www.rushlane.com/new-volvo-xc40-india-launch-price-12270656.html","as_of":"2026-10-15"}]},"generation":{"this_car":"First-generation XC40, imported fully built, sold in India as a D4 diesel from July 2018 until BS6 arrived in 2020. Volvo no longer sells a petrol or diesel XC40 here.","timeline":[{"year":"Jul 2018","text":"XC40 launched in India as the D4 diesel, all-wheel drive; Momentum and Inscription added."},{"year":"Dec 2019","text":"T4 petrol R-Design added, front-wheel drive."},{"year":"2020","text":"The D4 diesel is replaced by the BS6 petrol."},{"year":"Sep 2022","text":"Facelift as the B4 mild-hybrid petrol, one Ultimate version, from Rs 43.20 lakh."},{"year":"Nov 2023","text":"Petrol XC40 discontinued; the electric XC40 Recharge stays as Volvo's entry car."}],"sources":[{"name":"Autocar India, Volvo XC40 Momentum, Inscription variants launched (16 Jul 2018)","url":"https://www.autocarindia.com/car-news/volvo-xc40-momentum-inscription-variants-launched-409052","as_of":"2026-10-15"},{"name":"Autocar India, full details of Volvo XC40 for India revealed (15 Dec 2017)","url":"https://www.autocarindia.com/car-news-amp/full-details-of-volvo-xc40-for-india-revealed-406825","as_of":"2026-10-15"},{"name":"Autocar Professional, Volvo XC40 T4 R-Design petrol launched (14 Dec 2019)","url":"https://autocarpro.in/news-national/volvo-xc40-t4-rdesign-petrol-model-launched-at-rs-399-lakh-44907","as_of":"2026-10-15"},{"name":"Rushlane, 2020 Volvo XC40 petrol review: the D4 diesel replaced by the BS6 petrol","url":"https://www.rushlane.com/2020-volvo-xc40-review-12351460.html","as_of":"2026-10-15"},{"name":"CarWale, Volvo XC40 discontinued in India (10 Nov 2023)","url":"https://www.carwale.com/news/volvo-xc40-discontinued-in-india/","as_of":"2026-10-15"}],"peek":"First generation, D4 diesel; no fuel-engined XC40 on sale today"}},
